import{_ as p,a0 as o,w as r,s as c,ao as n,I as t,x as a,a1 as l,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"McFly：利用神經網絡為 Bash 提供歷史命令搜索功能 | LCTT x X-CMD","titleTemplate":false,"description":"McFly：利用神經網絡為 Bash 提供歷史命令搜索功能 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"McFly：利用神經網絡為 Bash 提供歷史命令搜索功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"McFly：利用神經網絡為 Bash 提供歷史命令搜索功能 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181210 McFly - A Replacement To ‘Ctrl-R- Bash History Search Feature","title":"McFly：利用神經網絡為 Bash 提供歷史命令搜索功能","tag":"201901","desc":""},"relativePath":"201901/20181210 McFly - A Replacement To ‘Ctrl-R- Bash History Search Feature.md","filePath":"[post].md"}'),h={name:"201901/20181210 McFly - A Replacement To ‘Ctrl-R- Bash History Search Feature.md"};function d(g,s,u,b,f,m){const i=o("Link");return r(),c("div",null,[s[19]||(s[19]=n('<h1 id="mcfly-利用神經網絡為-bash-提供歷史命令搜索功能" tabindex="-1">McFly：利用神經網絡為 Bash 提供歷史命令搜索功能 <a class="header-anchor" href="#mcfly-利用神經網絡為-bash-提供歷史命令搜索功能" aria-label="Permalink to “McFly：利用神經網絡為 Bash 提供歷史命令搜索功能”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/mcfly-720x340.png" alt=""></p><p>假如你在命令列模式下渡過了很長時間，那麼你必定使用過或者聽説過 BASH 的 <strong>反向搜索</strong> 功能，在 Bash 中執行反向搜索功能的快捷鍵是 <code>Ctrl+r</code>。通過使用這個特性，我們可以找到我們執行過的命令而無需再次輸入它們。當然，你可以使用上下鍵來搜索你的 bash 命令記錄，但使用 <code>Ctrl+r</code> 快捷鍵可以讓這個搜索過程更簡單快速。今天我找尋到了 Bash 歷史命令搜索特性 <code>Ctrl+r</code> 的一個替代品，它就是 McFly。McFly 是一個使用 Rust 編程語言寫就的簡潔工具，自帶一個智能的搜索引擎，用來替換默認的 <code>Ctrl+r</code> 這個 Bash 歷史命令搜索功能。 McFly 提供的命令建議都是通過一個小巧的 <strong>神經網絡</strong> 來實時排序給出的。</p><p>McFly 重新綁定了 <code>Ctrl+r</code> 快捷鍵，可以從你的 Bash 歷史命令中找到所有最近執行過的命令。它通過追溯下面的信息來增強你的 shell 歷史命令搜索特性：</p><ul><li>命令結束狀態</li><li>當你運行命令時的時間戳</li><li>以及你運行命令的執行目錄</li></ul><p>它將所有追溯的信息保存在一個 SQLite 資料庫中。由於它追溯了命令的歷史結束狀態，所以你可以很輕易地忽略掉失敗的命令。聽起來很酷，對吧？</p><p>在給出一個命令建議時，它將考慮如下因素：</p><ul><li>你在哪個目錄執行的這個命令，將來你很有可能在相同的目錄重複這個命令</li><li>在你執行這個命令之前，執行過什麼命令</li><li>你執行這個命令有多頻繁</li><li>你最後執行該命令的時間</li><li>你是否在 McFly 中選擇過這個命令</li><li>以及這個命令的歷史結束狀態。因為你很有可能不會去執行失敗過的命令，對吧？</li></ul><p>McFly 維護着你的默認 Bash 歷史文件，所以你可以隨時停止使用它。McFly 也並不只服務於 BASH， 它也可以擴展到其他 shell 程序。</p><h3 id="安裝-mcfly" tabindex="-1">安裝 McFly <a class="header-anchor" href="#安裝-mcfly" aria-label="Permalink to “安裝 McFly”">​</a></h3>',10)),t("p",null,[s[1]||(s[1]=a("在 Linux 中，McFly 可以使用 Linuxbrew 來安裝。如若你還沒有安裝過 Linuxbrew，那麼你可以參考下面的這個鏈接。（LCTT 譯註：從其 ",-1)),l(i,{href:"https://github.com/cantino/mcfly"},{default:e(()=>[...s[0]||(s[0]=[a("GitHub 主頁",-1)])]),_:1}),s[2]||(s[2]=a("瞭解到也可以下載其二進制來使用。）",-1))]),t("ul",null,[t("li",null,[l(i,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:e(()=>[...s[3]||(s[3]=[a("Linuxbrew：一個用於 Linux 和 Mac OS X 的通用包管理",-1)])]),_:1})])]),s[20]||(s[20]=n(`<p>一旦安裝好了 Linuxbrew，運行下面的命令來安裝 McFly：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew tap cantino/mcfly https://github.com/cantino/mcfly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ brew install mcfly</span></span></code></pre></div><p>在安裝完成後，你將看到下面的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>==&gt; Installing mcfly from cantino/mcfly</span></span>
<span class="line"><span>==&gt; Downloading https://github.com/cantino/mcfly/releases/download/v0.2.5/mcfly-v0</span></span>
<span class="line"><span>==&gt; Downloading from https://github-production-release-asset-2e65be.s3.amazonaws.c</span></span>
<span class="line"><span>######################################################################## 100.0%</span></span>
<span class="line"><span>==&gt; ONE MORE STEP! Edit ~/.bashrc and add the following:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ -f $(brew --prefix)/opt/mcfly/mcfly.bash ]; then</span></span>
<span class="line"><span>. $(brew --prefix)/opt/mcfly/mcfly.bash</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>🍺 /home/linuxbrew/.linuxbrew/Cellar/mcfly/v0.2.5: 4 files, 3.5MB, built in 33 seconds</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/install-mcfly.png" alt=""></p><p>正如你上面看到的那樣，在使用 McFly 之前我們需要再做一些配置。</p><p>將下面幾行添加到你的 <code>~/.bashrc</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if [ -f $(brew --prefix)/opt/mcfly/mcfly.bash ]; then</span></span>
<span class="line"><span>. $(brew --prefix)/opt/mcfly/mcfly.bash</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>最後，再運行下面的命令來讓更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>當你第一次執行上面的這個命令時，你的 BASH 歷史將會被導入 McFly 的資料庫。依據你的 bash 歷史文件的大小，這個過程將花費一些時間。一旦導入完成，你講看到下面的提示信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>McFly: Importing Bash history for the first time. This may take a minute or two...done.</span></span></code></pre></div><p>現在你就可以使用 McFly 了。</p><h3 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h3><p>要在你的命令歷史中執行搜索，只需要鍵入 <code>mcfly search</code> 再加上命令名的一部分，最後敲擊回車鍵即可。Mcfly 將會基於你剛才鍵入的搜索查詢語句給出命令建議。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly search &lt;part-of-the-command&gt;</span></span></code></pre></div><p>例如我鍵入了下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly search mk</span></span></code></pre></div><p>下面展示的是我 Ubuntu 機子上的示例輸出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/mcfly-command-1.png" alt=""></p><p>如你所見，我已經使用過 <code>mkdir</code> 這個命令兩次。假如你想從這些命令建議中執行其中之一，只需使用上下鍵來選擇它，然後敲擊<strong>回車鍵</strong>來執行它就可以了。假如你想編輯其中一個命令，則需要先選擇它，然後敲 <code>TAB</code> 鍵將這個命令放置到終端中，最後在運行它之前更改它就行了。要從歷史中刪除已經選擇的命令，按 <code>F2</code> 即可。</p><p>或者，輸入下面的命令來打開歷史搜索，然後輸入任意一個命令或者命令的一部分來從你的歷史命令中查看它提供的建議。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly search</span></span></code></pre></div><p>在你輸入的同時， McFly 將會展示命令的提示。</p><p>下面是一個介紹 McFly 的簡短演示視頻：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/mcfly-demo.gif" alt=""></p><p>你還可以使用下面的命令來查看幫助：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mcfly --help</span></span></code></pre></div><h3 id="移除-mcfly" tabindex="-1">移除 McFly <a class="header-anchor" href="#移除-mcfly" aria-label="Permalink to “移除 McFly”">​</a></h3><p>不喜歡 McFly，沒問題！可以使用下面的命令來移除它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew uninstall mcfly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ brew untap cantino/mcfly</span></span></code></pre></div><p>最後，移除先前添加到 <code>~/.bashrc</code> 文件中的幾行命令。</p><p>好了，這些就是所有了，更多精彩內容敬請期待，請保存關注！</p><p>乾杯！</p><hr>`,35)),t("p",null,[s[5]||(s[5]=a("via: ",-1)),l(i,{href:"https://www.ostechnix.com/mcfly-a-replacement-to-ctrlr-bash-history-search-feature/"},{default:e(()=>[...s[4]||(s[4]=[a("https://www.ostechnix.com/mcfly-a-replacement-to-ctrlr-bash-history-search-feature/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("作者：",-1)),l(i,{href:"https://www.ostechnix.com/author/sk/"},{default:e(()=>[...s[6]||(s[6]=[a("SK",-1)])]),_:1}),s[11]||(s[11]=a(" 選題：",-1)),l(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),l(i,{href:"https://github.com/FSSlc"},{default:e(()=>[...s[8]||(s[8]=[a("FSSlc",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),l(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=a("本文由 ",-1)),l(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),l(i,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const x=p(h,[["render",d]]);export{w as __pageData,x as default};
